def game(A, B):
    if A < 1 or B < 1:
        return "Non-drinkers can't play"
    mike_total = 0
    joe_total = 0
    turn = 1
    while True:
        if turn % 2 == 1:  # Mike's turn
            mike_total += turn
            if mike_total > A:
                return "Joe"
        else:  # Joe's turn
            joe_total += turn
            if joe_total > B:
                return "Mike"
        turn += 1
